source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # Ignore a diagonal run that already contains two different repeated-color
    # segments; extend the remaining repeated-color diagonal pairs.
    mixed_double_runs = set()
    for dr, dc in ((1, -1), (1, 1)):
        for r in range(h):
            for c in range(w):
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] != bg:
                    continue
                vals = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != bg:
                    vals.append((rr, cc, grid[rr][cc]))
                    rr += dr; cc += dc
                if len(vals) >= 4:
                    for i in range(len(vals)-3):
                        a, b, c1, d = (v[2] for v in vals[i:i+4])
                        if a == b and c1 == d and a != c1:
                            mixed_double_runs.add((dr, dc, tuple((x[0],x[1]) for x in vals)))
                            break
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, -1), (1, 1)):
                r2, c2 = r + dr, c + dc
                if not (0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == color):
                    continue
                # Skip if both repeated-color segments are on this same run.
                skipped = False
                rr, cc = r, c
                while 0 <= rr-dr < h and 0 <= cc-dc < w and grid[rr-dr][cc-dc] != bg:
                    rr -= dr; cc -= dc
                vals=[]; qr,qc=rr,cc
                while 0<=qr<h and 0<=qc<w and grid[qr][qc]!=bg:
                    vals.append(grid[qr][qc]); qr+=dr; qc+=dc
                if len(vals)>=4 and any(vals[i]==vals[i+1] and vals[i+2]==vals[i+3] and vals[i]!=vals[i+2] for i in range(len(vals)-3)):
                    skipped=True
                if skipped: continue
                for rr, cc, sr, sc in ((r2+dr,c2+dc,dr,dc),(r-dr,c-dc,-dr,-dc)):
                    while 0<=rr<h and 0<=cc<w and grid[rr][cc]==bg:
                        out[rr][cc]=color
                        rr+=sr;cc+=sc
    return out
'''
